import { enableProdMode } from '@angular/core';
import { bootstrapApplication } from '@angular/platform-browser';
import { appConfig } from './app.config';
import { APP_DI_CONFIG } from './app/app-config';
import { AppRootComponent } from './app/app-root.component';
import { AppConfigConstants, environment } from './environments/environment';

if (environment.production) {
	console.info('enableProdMode()');
	enableProdMode(); //needed in standalone. NG won't automatically inject it during production build.
	if (window) {
		window.console.debug = function () { }; //generally I don't use console.log()
	}
}

console.debug('AppConfigConstants: ' + JSON.stringify(AppConfigConstants));

switchPrebuiltTheme(AppConfigConstants.themeName ?? 'azure-blue');

//registerLocaleData(localeEnAu);
console.debug('languages: ' + JSON.stringify(window.navigator.language));
APP_DI_CONFIG.init();

bootstrapApplication(AppRootComponent, appConfig)
	.catch(err => console.error(err));

function switchPrebuiltTheme(themeName: string) {
	const head = document.getElementsByTagName('head')[0];
	const existingLink = document.getElementById('material-theme') as HTMLLinkElement;
	if (existingLink) {
		existingLink.href = `assets/themes/${themeName}.css`;
	} else {
		const link = document.createElement('link');
		link.id = 'material-theme';
		link.rel = 'stylesheet';
		link.href = `assets/themes/${themeName}.css`;
		head.appendChild(link);
	}
	// Limitations switchTheme
	// - Prebuilt themes are not compatible with Material 3’s CSS variable system.
	// - You cannot mix prebuilt themes with mat.theme()-based theming.
	// - Prebuilt themes do not support dynamic palette generation or density/typography overrides.
}

