import { BreakpointObserver, Breakpoints } from '@angular/cdk/layout';
import { CommonModule } from '@angular/common';
import { AfterViewInit, Component, Inject, OnDestroy, OnInit } from '@angular/core';
import { MatIconRegistry } from '@angular/material/icon';
import { DomSanitizer, Title } from '@angular/platform-browser';
import { NavigationEnd, Router, RouterModule } from '@angular/router';
import { AlertService, DIALOG_ACTIONS_ALIGN, NmceComponentsModule } from 'nmce';
import { AppConfigConstants } from '../environments/environment';
import { AUTH_STATUSES, LoginMessage, LoginStatus, STARTUP_STATUSES } from './_authServices/tokenInterceptor';
import { UpdateAppService } from './_authServices/updateApp.service';
import { APP_DI_CONFIG } from './app-config';

/**
 * Root component bootstrapped by AppModule. Provide startup nav structures in html, and init some basic services like SignalR, alertService and snackbar.
 */
@Component({
	selector: 'app-root',
	templateUrl: 'app-root.component.html',
	standalone: true,
	imports: [
		CommonModule, RouterModule, NmceComponentsModule
	]
})
export class AppRootComponent implements OnInit, OnDestroy, AfterViewInit {
	title = APP_DI_CONFIG.siteName;

	htmlVersion?: string;
	htmlBuildTime?: number;

	get isSmallScreen() { return APP_DI_CONFIG.isSmallScreen; }

	private displayNameMap = new Map([
		[Breakpoints.XSmall, 'XSmall'],
		[Breakpoints.Small, 'Small'],
		[Breakpoints.Medium, 'Medium'],
		[Breakpoints.Large, 'Large'],
		[Breakpoints.XLarge, 'XLarge'],
	]);

	private chronologyEnabled?: true;

	private authBroadcastChannel = new BroadcastChannel('fonlow.auth.channel');

	/**
	 * Initialize some root level services or components
	 */
	constructor(
		private titleService: Title,
		private alertService: AlertService,
		private router: Router,
		private sanitizer: DomSanitizer,
		private iconRegistry: MatIconRegistry,
		//private langSubjectService: LangSubjectService,
		//@Inject(DOCUMENT) private indexDoc: Document,
		breakpointObserver: BreakpointObserver,
		@Inject(DIALOG_ACTIONS_ALIGN) public actionsAlign: 'start' | 'center' | 'end',
		private updateAppService: UpdateAppService,
	) {
		// alertService to handle message emitted via SubjectMessage.
		iconRegistry.setDefaultFontSetClass('material-symbols-outlined');
		APP_DI_CONFIG.DialogActionsAlign = actionsAlign;
		this.alertService.initOnce();
		const smallScreenBreakpoint = AppConfigConstants.smallScreenBreakpoint ?? 'XSmall'; //expected Small or XSmall @ https://material.angular.io/cdk/layout/overview
		breakpointObserver.observe([Breakpoints.XSmall,
		Breakpoints.Small,
		Breakpoints.Medium,
		Breakpoints.Large,
		Breakpoints.XLarge,]).subscribe(result => {
			for (const query of Object.keys(result.breakpoints)) {
				if (result.breakpoints[query]) {
					const currentScreenSize = this.displayNameMap.get(query) ?? 'Unknown';
					//this.alertService.info(`Screen query: ${query} ${currentScreenSize} ${JSON.stringify(result)}` + currentScreenSize + ' ' + query);
					APP_DI_CONFIG.isSmallScreen = currentScreenSize.indexOf(smallScreenBreakpoint) >= 0;
					console.debug("isSmallScreen: " + APP_DI_CONFIG.isSmallScreen);
					if (APP_DI_CONFIG.isSmallScreen) { // if the browser become small, cancel chronologyEnabled if it is ever true.
						if (APP_DI_CONFIG.chronologyEnabled) {
							this.chronologyEnabled = APP_DI_CONFIG.chronologyEnabled;
							APP_DI_CONFIG.chronologyEnabled = false;
						}
					} else { //otherwise, recover its value.
						if (this.chronologyEnabled) {
							APP_DI_CONFIG.chronologyEnabled = this.chronologyEnabled;
						}
					}
				}
			}
		}
		);

		this.displayNewVersions();

		this.authBroadcastChannel.onmessage = (ev: MessageEvent<LoginMessage>) => {
			if (ev.data.senderId !== STARTUP_STATUSES.localTabId) {
				if (ev.data.status === LoginStatus.LoggedIn) {
					if (this.inAlbumView) {
						this.router.navigate(['/authoredit/albums']);
					} else {
						this.router.navigate(['/authoredit']);
					}

					console.info("App Logged In");
				} else if (ev.data.status === LoginStatus.LoggedOut) {
					if (this.inAlbumView) {
						this.router.navigate(['/albums']);
					} else {
						this.router.navigate(['/']);
					}

					console.info("App Logged Out");
				}
			}
		}
	}


	ngOnInit(): void {
		this.updateAppService.checkAvailable();

		if (this.title) {
			this.titleService.setTitle(this.title);
		} //otherwise the one in index.html remains.

		this.router.events.subscribe((evt) => {
			if (!(evt instanceof NavigationEnd)) {
				return;
			}
			window.scrollTo(0, 0);
		});

		const icons: { name: string, path: string }[] = [
			{ name: 'c_fan', path: 'assets/icons/fan.svg' },
			{ name: 'c_jian', path: 'assets/icons/jian.svg' },
			//{ name: 'c_clipboard_copy', path: 'assets/icons/clipboard-copy.svg' },
		];

		for (const k of icons) {
			this.iconRegistry.addSvgIcon(k.name, this.sanitizer.bypassSecurityTrustResourceUrl(k.path));
		}
	}

	ngAfterViewInit() {
	}

	get loggedIn() {
		return AUTH_STATUSES.loggedIn;
	}

	ngOnDestroy(): void {
	}

	private displayNewVersions() {
		const oldHtmlVersion = localStorage['Fonlow.PoemsCollection.HtmlVersion'];
		if (oldHtmlVersion !== APP_DI_CONFIG.version) {
			this.htmlVersion = APP_DI_CONFIG.version;
			localStorage['Fonlow.PoemsCollection.HtmlVersion'] = APP_DI_CONFIG.version;
		}

		const oldHtmlBuildTime = localStorage['Fonlow.PoemsCollection.HtmlBuildTime'];
		if (oldHtmlBuildTime !== APP_DI_CONFIG.buildTime?.toString()) {
			this.htmlBuildTime = APP_DI_CONFIG.buildTime;
			localStorage['Fonlow.PoemsCollection.HtmlBuildTime'] = APP_DI_CONFIG.buildTime;
		}

		if (this.htmlBuildTime || this.htmlVersion) {
			this.alertService.success(APP_DI_CONFIG.siteName + ' is updated');
		}
	}

	get inAlbumView() {
		return this.router.url.indexOf('albums') >= 0;
	}
}
