import { Routes } from '@angular/router';
import { NotFoundComponent } from 'nmce';
import { AuthGuard } from './_guards/auth.guard';

export const routes: Routes = [
	{ path: '', loadChildren: () => import('./reader-view/reader-view.routes').then(m => m.READ_VIEW_ROUTES) },
	{ path: 'author/:authorIdx', loadChildren: () => import('./reader-view/reader-view.routes').then(m => m.READ_VIEW_ROUTES) },
	//{ path: 's2t', loadChildren: () => import('./reader-view/reader-view.module').then(m => m.ReaderViewModule) },
	//{ path: 't2s', loadChildren: () => import('./reader-view/reader-view.module').then(m => m.ReaderViewModule) },
	{ path: 'authoredit', loadChildren: () => import('./editor-view/editor-view.routes').then(m => m.EDITOR_VIEW_ROUTES), canActivate: [AuthGuard] },
	{ path: '**', component: NotFoundComponent }, // This must be the last

];
