import { inject } from '@angular/core';
import { ActivatedRouteSnapshot, CanActivateFn, Router, RouterStateSnapshot } from '@angular/router';
import { AUTH_STATUSES } from '../_authServices/tokenInterceptor';


/**
  Auth the internal user logged in and decide whether to route to a feature.
  NG15,16 want Fn. https://stackoverflow.com/questions/75564717/angulars-canactivate-interface-is-deprecated-how-to-replace-it
*/
export const AuthGuard: CanActivateFn = (route: ActivatedRouteSnapshot, state: RouterStateSnapshot) => {
	if (AUTH_STATUSES.username) { //Often the span of token is 2 weeks by default provided by Aps.net identity 2. So generally no need to check the token expiry date as well.
		return true;
	}
	const router = inject(Router);

	// not logged in so redirect to login page
	router.navigate(['/'], { queryParams: { returnUrl: state.url } });
	return false;
}

